css:
.relative {
  position: relative
}

.mb-2 {
  margin-bottom: 0.5rem
}

.mb-4 {
  margin-bottom: 1rem
}

.mt-1 {
  margin-top: 0.25rem
}

.block {
  display: block
}

.flex {
  display: flex
}

.h-6 {
  height: 1.5rem
}

.h-80 {
  height: 20rem
}

.w-6 {
  width: 1.5rem
}

.w-64 {
  width: 16rem
}

.w-full {
  width: 100%
}

.flex-row {
  flex-direction: row
}

.flex-col {
  flex-direction: column
}

.justify-center {
  justify-content: center
}

.justify-between {
  justify-content: space-between
}

.gap-3 {
  gap: 0.75rem
}

.overflow-hidden {
  overflow: hidden
}

.rounded {
  border-radius: 0.25rem
}

.border {
  border-width: 1px
}

.border-sky-500 {
  --tw-border-opacity: 1;
  border-color: rgb(14 165 233 / var(--tw-border-opacity))
}

.bg-sky-50 {
  --tw-bg-opacity: 1;
  background-color: rgb(240 249 255 / var(--tw-bg-opacity))
}

.bg-sky-500 {
  --tw-bg-opacity: 1;
  background-color: rgb(14 165 233 / var(--tw-bg-opacity))
}

.fill-current {
  fill: currentColor
}

.p-2 {
  padding: 0.5rem
}

.p-3 {
  padding: 0.75rem
}

.text-center {
  text-align: center
}

.text-right {
  text-align: right
}

.text-sm {
  font-size: 0.875rem;
  line-height: 1.25rem
}

.text-xs {
  font-size: 0.75rem;
  line-height: 1rem
}

.font-bold {
  font-weight: 700
}

.text-gray-700 {
  --tw-text-opacity: 1;
  color: rgb(55 65 81 / var(--tw-text-opacity))
}

.text-sky-50 {
  --tw-text-opacity: 1;
  color: rgb(240 249 255 / var(--tw-text-opacity))
}

.text-sky-500 {
  --tw-text-opacity: 1;
  color: rgb(14 165 233 / var(--tw-text-opacity))
}

.opacity-50 {
  opacity: 0.5
}

.shadow {
  --tw-shadow: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --tw-shadow-colored: 0 1px 3px 0 var(--tw-shadow-color), 0 1px 2px -1px var(--tw-shadow-color);
  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow)
}

.outline-none {
  outline: 2px solid transparent;
  outline-offset: 2px
}

.after\:absolute::after {
  content: var(--tw-content);
  position: absolute
}

.after\:-right-4::after {
  content: var(--tw-content);
  right: -1rem
}

.after\:-top-4::after {
  content: var(--tw-content);
  top: -1rem
}

.after\:-z-10::after {
  content: var(--tw-content);
  z-index: -10
}

.after\:h-24::after {
  content: var(--tw-content);
  height: 6rem
}

.after\:w-24::after {
  content: var(--tw-content);
  width: 6rem
}

.after\:rounded-full::after {
  content: var(--tw-content);
  border-radius: 9999px
}

.after\:bg-sky-300::after {
  content: var(--tw-content);
  --tw-bg-opacity: 1;
  background-color: rgb(125 211 252 / var(--tw-bg-opacity))
}

.after\:blur-xl::after {
  content: var(--tw-content);
  --tw-blur: blur(24px);
  filter: var(--tw-blur) var(--tw-brightness) var(--tw-contrast) var(--tw-grayscale) var(--tw-hue-rotate) var(--tw-invert) var(--tw-saturate) var(--tw-sepia) var(--tw-drop-shadow)
}

